export type CopyKey = (typeof rows)[number][3];
export type CopyField = {
  key: CopyKey;
  page: PageId;
  section: string;
  label: string;
  kind: Kind;
};
export const defaultCopy = Object.fromEntries(
  rows.map((row) => [row[3], row[4]]),
) as Record<CopyKey, string>;
export const copyFields: CopyField[] = rows.map((row) => ({
  page: row[0],
  section: row[1],
  label: row[2],
  key: row[3],
  kind: (row as Row)[5] ?? "text",
}));
